#ifndef BVML_KERNELS_H
#define BVML_KERNELS_H
#define BVML_KERNEL_SAXPY "; bvml_saxpy — out[i] = a*x[i] + y[i]\n; args: S16=xbase S17=ybase S18=outbase S19=a(float bits)\n;       S20=count S21=step(4) S22=one(1)\n.kernel saxpy\n    MOV S23, S16\n    MOV S24, S17\n    MOV S25, S18\n    MOV S26, S20\nloop:\n    LOAD S1, S23, 0\n    LOAD S2, S24, 0\n    MUL S3, S19, S1\n    ADD S3, S3, S2\n    STORE S25, S3, 0\n    IADD S23, S23, S21\n    IADD S24, S24, S21\n    IADD S25, S25, S21\n    ISUB S26, S26, S22\n    CMP P0, S26, S0\n    BR_COND@P0 done\n    BR loop\ndone:\n    EXIT\n.end"
#define BVML_KERNEL_DOT "; bvml_dot — out[0] = sum(x[i]*y[i])\n; args: S16=xbase S17=ybase S18=outbase S19=count\n;       S20=step(4) S21=one(1)\n.kernel dot\n    MOV S23, S16\n    MOV S24, S17\n    MOV S25, S19\n    ADDi S26, S0, 0\ndloop:\n    LOAD S1, S23, 0\n    LOAD S2, S24, 0\n    MAD S26, S1, S2\n    IADD S23, S23, S20\n    IADD S24, S24, S20\n    ISUB S25, S25, S21\n    CMP P0, S25, S0\n    BR_COND@P0 ddone\n    BR dloop\nddone:\n    STORE S18, S26, 0\n    EXIT\n.end"
#define BVML_KERNEL_GEMM "; bvml_gemm — C[r][c] = alpha * sum_over_k(A[r][k]*B[k][c]) + beta*C[r][c]\n; Per-element launch (row-major A[M,K], B[K,N], C[M,N]).\n; args: S16=Arow S17=Bcol S18=outptr S19=count(K) S20=stepA(4)\n;       S21=stepB(N*4) S22=one(1) S23=alpha(bits) S24=beta(bits)\n.kernel gemm\n    MOV S1, S0\n    MOV S2, S16\n    MOV S3, S17\n    MOV S4, S19\ngloop:\n    CMP P0, S4, S0\n    BR_COND@P0 gdone\n    LOAD S5, S2, 0\n    LOAD S6, S3, 0\n    MAD S1, S5, S6\n    IADD S2, S2, S20\n    IADD S3, S3, S21\n    ISUB S4, S4, S22\n    BR gloop\ngdone:\n    MUL S1, S1, S23\n    LOAD S7, S18, 0\n    MUL S10, S24, S7\n    ADD S1, S1, S10\n    STORE S18, S1, 0\n    EXIT\n.end"
#endif
